389	      const state: FolderState = {
390	        ipnsName,
391	        folderKey,
392	        ipnsKeypair,
393	        sequenceNumber: result.sequenceNumber,
394	        children: result.metadata.children,
395	        metadata: result.metadata,
396	        lastLoadedAt: Date.now(),
397	      };
398	
